import React, { useEffect, useState } from 'react';
import { getAssociatedFranchises, createUserExamData } from '../services/api';

const AssociatedFranchises = () => {
  const [franchises, setFranchises] = useState([]);
  const [examData, setExamData] = useState({
    franchiseId: '',  // No franchise selection here
    examName: '',
    date: '',
    studentsAttended: '',
  });
  const [error, setError] = useState(null);
  const [success, setSuccess] = useState('');
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    const fetchFranchises = async () => {
      setLoading(true);
      try {
        const data = await getAssociatedFranchises();
        setFranchises(data);
        
        if (data.length > 0) {
          // Automatically associate with the first franchise in the list
          setExamData({ ...examData, franchiseId: data[0]._id });
        }
      } catch (error) {
        setError('Failed to fetch associated franchises.');
      } finally {
        setLoading(false);
      }
    };

    fetchFranchises();
  }, []);  // Empty dependency array ensures this runs only once

  const handleExamDataChange = (e) => {
    setExamData({
      ...examData,
      [e.target.name]: e.target.value,
    });
  };

  const handleCreateExamData = async (e) => {
    e.preventDefault();
  
    // Validate the date format
    if (!examData.date) {
      setError('Please provide the exam date.');
      return;
    }
  
    setLoading(true);
    try {
      // Ensure the date is in the right format (YYYY-MM-DD)
      const formattedDate = new Date(examData.date).toISOString().split('T')[0];
  
      // Send the data with the formatted date
      await createUserExamData({ ...examData, date: formattedDate });
      setSuccess('Exam data created successfully!');
      setExamData({ franchiseId: '', examName: '', date: '', studentsAttended: '' });
      setError(null);
    } catch (error) {
      setError(error.response?.data?.message || 'Failed to create exam data.');
    } finally {
      setLoading(false);
    }
  };
  

  useEffect(() => {
    if (success) {
      const timer = setTimeout(() => setSuccess(''), 3000);
      return () => clearTimeout(timer);
    }
  }, [success]);

  return (
    <div>
      <h2>Associated Franchises</h2>
      {loading && <p>Loading...</p>}
      {error && <p style={{ color: 'red' }}>{error}</p>}
      {success && <p style={{ color: 'green' }}>{success}</p>}

      {franchises.length > 0 ? (
        <ul>
          {franchises.map((franchise) => (
            <li key={franchise._id}>{franchise.name}</li>
          ))}
        </ul>
      ) : (
        <p>No associated franchises found.</p>
      )}

      <h3>Create Exam Data</h3>
      <form onSubmit={handleCreateExamData}>
        {/* Removed Franchise select dropdown */}

        <div>
          <label htmlFor="examName">Exam Name</label>
          <input
            type="text"
            name="examName"
            value={examData.examName}
            onChange={handleExamDataChange}
            required
          />
        </div>

        <div>
          <label htmlFor="date">Exam Date</label>
          <input
            type="date"
            name="date"
            value={examData.date}
            onChange={handleExamDataChange}
            required
          />
        </div>

        <div>
          <label htmlFor="studentsAttended">Students Attended</label>
          <input
            type="number"
            name="studentsAttended"
            value={examData.studentsAttended}
            onChange={handleExamDataChange}
            required
          />
        </div>

        <button type="submit" disabled={loading}>
          {loading ? 'Submitting...' : 'Create Exam Data'}
        </button>
      </form>
    </div>
  );
};

export default AssociatedFranchises;
